{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "자전거전용도로 등 자전거이용시설이 설치된 곳에서 서울시 자전거 조례가 시민에게 두는 이용 의무 수준",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울시 자전거 조례는 자전거전용도로 등 자전거이용시설이 설치된 경우 자전거를 이용하는 시민이 해당 시설을 이용하도록 노력하여야 한다고 정한다. 따라서 시민에게 부과되는 의무 수준은 ‘반드시 그 길만 이용해야 한다’는 강제 의무가 아니라, 해당 시설을 이용하도록 노력하여야 하는 노력 의무이다.",
          "b_ids": "자전거:제4조제6항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "자전거전용도로가 설치된 곳에서 시민이 반드시 그 길만 이용해야 한다고 서울시 자전거 조례에 되어 있는지",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울시 자전거 조례는 자전거전용도로 등 자전거이용시설이 설치된 경우 자전거를 이용하는 시민이 해당 시설을 이용하도록 노력하여야 한다고 정할 뿐, 반드시 그 길만 이용해야 한다고 규정하지 않는다. 즉 조례는 이용 의무를 ‘노력하여야 한다’는 수준으로 두고 있으며, 강제적 전용 이용 의무를 두고 있지 않다.",
          "b_ids": "자전거:제4조제6항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
